/*
	VIOC_weapon_info.sqf - agregado por tools/vio_build.py (parche weapon_info; copia configurada, no es del autor de la
	mision). Fuente: work/v6_build/weapon_info/.

	"Info del arma" en el menu de equipo (MENU: Equipment):
	  - Boton "Info del arma" en el pie del menu (x 0.595, junto a "Taller de armas"). Abre/cierra un panel sobre la parte
	    de arriba a la derecha del menu (contenedores e inventario de la unidad; las ranuras de armas siguen visibles).
	  - Con el panel abierto, cada objeto que eliges en la lista de la tienda muestra su ficha. Los botones del panel
	    "Arma principal", "Lanzador" y "Pistola" muestran la ficha de las armas que lleva la unidad que editas.
	  - Ficha de un arma: nombre, tipo/rol (BIS_fnc_itemType), descripcion, si tu tienda la vende y su precio, TODA la
	    municion compatible por boca (magazines[] + magazineWell de CfgMagazineWells + compatibleMagazines, sin repetir),
	    marcando la que vende tu tienda con su precio (y el nivel de Gear si hace falta uno mayor), accesorios
	    compatibles por ranura (mira, boca, lateral, bipode) marcando los que vende tu tienda, modos de fuego, alza y
	    "como se usa" en palabras simples (rol del arma; en lanzadores: guiado o no, fijacion AA/AT, ataque por arriba,
	    desechable, distancia de fijacion; leidos de CfgWeapons/CfgAmmo).
	  - Ficha de un cargador o accesorio: datos, precio y las armas de tu tienda que lo usan.
	  - Todo se lee de la configuracion del juego solo en el cliente y se guarda por clase (VIOC_GI_CACHE); los precios
	    y el nivel se miran cada vez (son las variables de la tienda de la mision). Si algo no esta en la configuracion,
	    la ficha lo dice y no falla.
	  - Ademas (VIOC_GI_fnc_weaponMags): la lista "vinculada" de cargadores del menu (debajo de la tienda) incluye los de
	    magazineWell, para que aparezca la municion correcta de las armas modernas (CUP/RHS/CBA).
	Solo cliente (hasInterface). Parametro de lobby VIOC_WEAPON_INFO (0 = No, 1 = Si). No crea nada en el mapa.
	Consola (Ejecucion local, con el menu de equipo abierto o no):
	    ["rhs_weap_m4a1_carryhandle"] call VIOC_GI_fnc_show;       ficha (en el panel, o en un aviso si no esta abierto)
	    count (["rhs_weap_m4a1_carryhandle"] call VIOC_GI_fnc_weaponMags)   cargadores compatibles (todas las bocas)
	    VIOC_GI_CACHE = createHashMap;                                vaciar la cache
*/
if (!hasInterface) exitWith {};
if ((missionNamespace getVariable ["VIOC_WEAPON_INFO", 1]) < 1) exitWith {};

VIOC_GI_CACHE = createHashMap;		//--- clase en minusculas -> datos de configuracion del arma (no dependen de la tienda)
VIOC_GI_ITEM = "";					//--- ultimo objeto elegido en la tienda
VIOC_GI_REV = [];					//--- indice inverso [cargador -> armas, accesorio -> armas] de tu tienda (se arma una vez)
VIOC_GI_REV_BUSY = false;
VIOC_GI_IDCS = [70060, 70061, 70062, 70063, 70064, 70065, 70066, 70067];	//--- fondo, titulo, 3 botones, cerrar, grupo, texto
//--- Ranuras de accesorio: [nombre de CTI_CL_FNC_GetCompatibleItems, ItemInfo type, titulo]
VIOC_GI_SLOTS = [["optic", 201, "Miras"], ["muzzle", 101, "Bocas (supresor, apagallamas)"], ["pointer", 301, "Laterales (laser, linterna)"], ["bipod", 302, "Bipodes y empunaduras"]];

//--- Texto de configuracion -> texto seguro para parseText: quita etiquetas (<br/> pasa a " / ") y escapa & y >.
VIOC_GI_fnc_txt = {
	params [["_s", "", [""]]];
	if (_s == "") exitWith {""};
	private _out = [];
	private _tag = [];
	private _in = false;
	{
		if (_in) then {
			if (_x == 62) then {
				_in = false;
				if (((toLower (toString _tag)) select [0, 2]) == "br") then {_out append (toArray " / ")};
				_tag = [];
			} else {
				_tag pushBack _x;
			};
		} else {
			switch (_x) do {
				case 60: {_in = true};
				case 38: {_out append (toArray "&amp;")};
				case 62: {_out append (toArray "&gt;")};
				case 10: {_out append (toArray " / ")};
				case 13: {};
				default {_out pushBack _x};
			};
		};
	} forEach (toArray _s);
	toString _out
};

//--- Nombre visible (seguro) de una clase de CfgWeapons/CfgMagazines/CfgVehicles/CfgGlasses.
VIOC_GI_fnc_name = {
	params [["_c", "", [""]], ["_root", "CfgWeapons"]];
	private _n = [getText (configFile >> _root >> _c >> "displayName")] call VIOC_GI_fnc_txt;
	if (_n == "") then {_n = _c};
	_n
};

//--- Nivel de mejora Gear del bando del jugador (como el menu de equipo).
VIOC_GI_fnc_level = {
	if (isNil "CTI_CO_FNC_GetSideUpgrades" || {isNil "CTI_UPGRADE_GEAR"}) exitWith {0};
	private _ups = (CTI_P_SideJoined) call CTI_CO_FNC_GetSideUpgrades;
	if (isNil "_ups" || {!(_ups isEqualType [])}) exitWith {0};
	private _l = _ups param [CTI_UPGRADE_GEAR, 0];
	if !(_l isEqualType 0) exitWith {0};
	_l
};

//--- [precio, nivel] si la tienda de tu bando tiene ese objeto (variable de la mision [[nivel, precio], tipo, "CfgXxx"]), si no [].
VIOC_GI_fnc_shop = {
	params [["_c", "", [""]]];
	if (_c == "") exitWith {[]};
	private _get = missionNamespace getVariable (toLower _c);
	if (isNil "_get" || {!(_get isEqualType [])} || {count _get < 3} || {!((_get select 0) isEqualType [])} || {!((_get select 2) isEqualType "")}) exitWith {[]};
	if !((_get select 2) in ["CfgWeapons", "CfgMagazines", "CfgVehicles", "CfgGlasses"]) exitWith {[]};
	private _lp = _get select 0;
	private _p = _lp param [1, 0];
	private _l = _lp param [0, 0];
	if (!(_p isEqualType 0) || {!(_l isEqualType 0)}) exitWith {[]};
	[_p, _l]
};

//--- Texto del precio de tienda: "$900" (verde), "$900, Gear nivel 2" (amarillo) o "" si no se vende.
VIOC_GI_fnc_priceTag = {
	params ["_shop", "_level"];
	if (count _shop == 0) exitWith {""};
	_shop params ["_p", "_l"];
	if (_l > _level) exitWith {format ["<t color='#F5D363'>$%1, Gear nivel %2</t>", _p, _l]};
	format ["<t color='#76F563'>$%1</t>", _p]
};

//--- Cargadores de una boca: magazines[] + los de sus magazineWell (CfgMagazineWells) + compatibleMagazines (2.10+).
//--- Sin repetir (minusculas), solo clases que existen, con balas y scope >= 1. Devuelve las clases con su nombre real.
VIOC_GI_fnc_muzzleMags = {
	params ["_w", "_m"];
	private _mc = if (_m == "this") then {configFile >> "CfgWeapons" >> _w} else {configFile >> "CfgWeapons" >> _w >> _m};
	private _list = getArray (_mc >> "magazines");
	{
		if (_x isEqualType "") then {
			{_list append (getArray _x)} forEach (configProperties [configFile >> "CfgMagazineWells" >> _x, "isArray _x", true]);
		};
	} forEach (getArray (_mc >> "magazineWell"));
	_list append (compatibleMagazines [_w, _m]);
	private _seen = createHashMap;
	private _out = [];
	{
		if (_x isEqualType "" && {_x != ""}) then {
			private _l = toLower _x;
			if !(_seen getOrDefault [_l, false]) then {
				_seen set [_l, true];
				private _mg = configFile >> "CfgMagazines" >> _x;
				if (isClass _mg && {getNumber (_mg >> "scope") >= 1} && {getNumber (_mg >> "count") > 0}) then {_out pushBack (configName _mg)};
			};
		};
	} forEach _list;
	_out
};

//--- Uso de la municion (solo cohetes, misiles, granadas...; las balas lo dicen en su nombre).
VIOC_GI_fnc_ammoTag = {
	params ["_mg"];
	private _a = getText (configFile >> "CfgMagazines" >> _mg >> "ammo");
	if (_a == "") exitWith {""};
	private _ac = configFile >> "CfgAmmo" >> _a;
	if !(isClass _ac) exitWith {""};
	private _sim = toLower getText (_ac >> "simulation");
	if (_sim == "shotbullet") exitWith {""};
	private _wh = toLower getText (_ac >> "warheadName");
	private _sub = if (isText (_ac >> "submunitionAmmo")) then {getText (_ac >> "submunitionAmmo")} else {""};
	switch (true) do {
		case (_sim in ["shotsmoke", "shotsmokex"]): {"humo"};
		case (_sim == "shotilluminating"): {"bengala"};
		case (_sim == "shotspread"): {"perdigones"};
		case (_sim == "shotmissile" && {getNumber (_ac >> "airLock") == 2}): {"antiaereo"};
		case (_wh == "tandemheat"): {"antitanque en tandem"};
		case (_wh == "heat"): {"antiblindaje (HEAT)"};
		case (_sub != ""): {"antiblindaje"};
		case (_wh == "ap"): {"perforante"};
		case (_wh == "he"): {"explosivo (infanteria, edificios)"};
		case (getNumber (_ac >> "indirectHitRange") >= 2): {"explosivo"};
		default {""};
	}
};

//--- Accesorios compatibles por ranura [miras, bocas, laterales, bipodes] (minusculas): lista de la mision
//--- (CTI_CL_FNC_GetCompatibleItems, la que usa el menu) + la de BIS (BIS_fnc_compatibleItems), por tipo de objeto.
VIOC_GI_fnc_attach = {
	params ["_w"];
	if !(isClass (configFile >> "CfgWeapons" >> _w)) exitWith {[[], [], [], []]};
	private _all = [];
	if (!isNil "CTI_CL_FNC_GetCompatibleItems") then {
		{
			private _l = [_w, _x select 0] call CTI_CL_FNC_GetCompatibleItems;
			if (!isNil "_l" && {_l isEqualType []}) then {_all append _l};
		} forEach VIOC_GI_SLOTS;
	};
	_all append ([_w] call BIS_fnc_compatibleItems);
	private _types = VIOC_GI_SLOTS apply {_x select 1};
	private _out = [[], [], [], []];
	{
		if (_x isEqualType "" && {isClass (configFile >> "CfgWeapons" >> _x)}) then {
			private _s = _types find (getNumber (configFile >> "CfgWeapons" >> _x >> "ItemInfo" >> "type"));
			if (_s >= 0) then {(_out select _s) pushBackUnique (toLower _x)};
		};
	} forEach _all;
	_out
};

//--- Datos de configuracion de un arma (se calculan una vez por clase).
//--- [nombre, tipo BIS, clase "cargada" (lanzadores desechables de CBA) o "", bocas [[boca, etiqueta, [cargadores]]],
//---  accesorios [4 listas], modos [textos], alza [min, max] o [], lineas de uso [textos], todos los cargadores (minusculas), descripcion]
VIOC_GI_fnc_wdata = {
	params ["_w"];
	private _key = toLower _w;
	private _c = VIOC_GI_CACHE getOrDefault [_key, []];
	if (count _c > 0) exitWith {_c};
	private _cfg = configFile >> "CfgWeapons" >> _w;
	private _name = [_w] call VIOC_GI_fnc_name;
	private _kind = ([_w] call BIS_fnc_itemType) param [1, ""];
	//--- lanzadores desechables de CBA: la municion y el guiado estan en la version "cargada"
	private _loaded = "";
	private _dcfg = configFile >> "CBA_DisposableLaunchers" >> _w;
	if (isArray _dcfg) then {
		_loaded = (getArray _dcfg) param [0, ""];
		if (!(_loaded isEqualType "") || {!isClass (configFile >> "CfgWeapons" >> _loaded)}) then {_loaded = ""};
	};
	private _src = if (_loaded != "") then {_loaded} else {_w};
	private _scfg = configFile >> "CfgWeapons" >> _src;
	//--- bocas y su municion
	private _muz = getArray (_scfg >> "muzzles");
	if (count _muz == 0) then {_muz = ["this"]};
	private _muzzles = [];
	private _allMags = [];
	{
		if (_x isEqualType "") then {
			private _m = _x;
			private _mags = [_src, _m] call VIOC_GI_fnc_muzzleMags;
			if (count _mags > 0) then {
				private _label = "";
				if (_m != "this") then {
					_label = [getText (_scfg >> _m >> "displayName")] call VIOC_GI_fnc_txt;
					if (_label == "") then {_label = _m};
				};
				_muzzles pushBack [_m, _label, _mags];
				{_allMags pushBackUnique (toLower _x)} forEach _mags;
			};
		};
	} forEach _muz;
	//--- modos de fuego que ve el jugador
	private _modes = [];
	{
		if (_x isEqualType "") then {
			private _mc = if (_x == "this") then {_cfg} else {_cfg >> _x};
			if (_x == "this" || {isClass _mc}) then {
				private _show = if (isNumber (_mc >> "showToPlayer")) then {getNumber (_mc >> "showToPlayer") != 0} else {true};
				if (_show) then {
					private _n = [getText (_mc >> "displayName")] call VIOC_GI_fnc_txt;
					if (_n == "") then {_n = if (_x == "this") then {"Unico"} else {_x}};
					private _auto = getNumber (_mc >> "autoFire") > 0;
					private _burst = getNumber (_mc >> "burst");
					private _how = if (_auto) then {"automatico"} else {if (_burst > 1) then {format ["rafaga de %1", _burst]} else {"tiro a tiro"}};
					if (_auto) then {
						private _rt = (_mc >> "reloadTime") call BIS_fnc_parseNumberSafe;
						if (_rt isEqualType 0 && {_rt > 0.01}) then {_how = format ["%1, unos %2 disparos/min", _how, round (60 / _rt)]};
					};
					_modes pushBack format ["%1 (%2)", _n, _how];
				};
			};
		};
	} forEach (getArray (_cfg >> "modes"));
	//--- alza (distancias de puesta a cero de la mira de hierro)
	private _zl = (getArray (_cfg >> "discreteDistance")) select {_x isEqualType 0 && {_x > 0}};
	private _zero = [];
	if (count _zl > 1) then {
		private _lo = 1e9;
		private _hi = 0;
		{_lo = _lo min _x; _hi = _hi max _x} forEach _zl;
		_zero = [_lo, _hi];
	};
	//--- como se usa (rol + guiado de lanzadores, en palabras simples)
	private _use = [];
	private _role = switch (_kind) do {
		case "AssaultRifle";
		case "Rifle": {"Fusil de asalto: arma principal para todo uso, eficaz hasta unos 300-400 m. Usa tiro a tiro a distancia y rafagas cortas de cerca."};
		case "MachineGun": {"Ametralladora: fuego de supresion y cobertura para tu grupo. Disparala tumbado o apoyada (bipode o apoyar el arma, tecla C por defecto) en rafagas cortas; recarga lento."};
		case "SniperRifle": {"Fusil de tirador / francotirador: precision a larga distancia (400 m o mas). Usa mira de aumento, ajusta el alza segun la distancia y dispara quieto o apoyado."};
		case "SubmachineGun": {"Subfusil: para corta distancia (hasta 100-150 m) e interiores; poco alcance y poca penetracion."};
		case "Shotgun": {"Escopeta: solo para muy corta distancia (menos de 50 m con perdigones)."};
		case "Handgun": {"Pistola: arma de respaldo para muy corta distancia."};
		case "GrenadeLauncher": {"Lanzagranadas: granadas en tiro curvo contra grupos y posiciones (unos 50-400 m). Calcula la distancia: la granada cae en parabola."};
		case "RocketLauncher": {"Lanzacohetes: contra vehiculos, blindados o posiciones segun la municion."};
		case "MissileLauncher": {"Lanzamisiles guiado."};
		case "Launcher": {"Lanzador."};
		default {""};
	};
	if (_role != "") then {_use pushBack _role};
	if (_loaded != "") then {_use pushBack "Desechable: viene cargado de fabrica, se dispara UNA vez y se tira. No necesitas comprar municion."};
	private _type = getNumber (_cfg >> "type");
	if (_type == 4 && {count _muzzles > 0}) then {
		private _mg = ((_muzzles select 0) select 2) select 0;
		private _ac = configFile >> "CfgAmmo" >> (getText (configFile >> "CfgMagazines" >> _mg >> "ammo"));
		if (isClass _ac) then {
			private _sim = toLower getText (_ac >> "simulation");
			private _canLock = getNumber (_scfg >> "canLock");
			private _air = getNumber (_ac >> "airLock");
			private _ir = getNumber (_ac >> "irLock") > 0;
			private _laser = getNumber (_ac >> "laserLock") > 0;
			private _man = getNumber (_ac >> "manualControl") > 0;
			private _prof = (getArray (_ac >> "flightProfiles")) apply {if (_x isEqualType "") then {toLower _x} else {""}};
			private _rng = getNumber (_ac >> "missileLockMaxDistance");
			if (_sim == "shotrocket") then {
				_use pushBack "Cohete NO guiado: apunta con la mira del lanzador y ajusta el alza segun la distancia; a mas de 300-400 m la caida es grande. Contra blindados pega en los lados o atras, no de frente.";
			};
			if (_sim == "shotmissile") then {
				switch (true) do {
					case (_air == 2): {_use pushBack "Antiaereo (AA): solo fija aviones y helicopteros. Manten la aeronave dentro de la mira hasta que se fije (tono continuo y recuadro) y dispara: el misil la sigue solo. Las bengalas pueden desviarlo."};
					case (_canLock > 0 && {!_man}): {_use pushBack "Guiado con fijacion (dispara y olvida): apunta al vehiculo y espera a que se fije (recuadro y tono) antes de disparar; despues el misil va solo."};
					case (_canLock > 0): {_use pushBack "Guiado: si lo fijas antes de disparar (recuadro y tono) sigue solo; si no, sigue tu punto de mira: manten la mira sobre el blanco hasta el impacto."};
					case (_man): {_use pushBack "Guiado por la mira: despues de disparar manten la mira sobre el blanco hasta el impacto; el misil va a donde apuntas."};
					default {_use pushBack "Misil sin fijacion: apunta directo al blanco."};
				};
				if (_air != 2 && {_canLock > 0}) then {
					if (_ir) then {_use pushBack "Fija blancos calientes: vehiculos con el motor encendido (uno frio y apagado cuesta mas)."};
					if (_laser) then {_use pushBack "Tambien sigue blancos marcados con un designador laser."};
					if (_air == 1) then {_use pushBack "Puede fijar tambien helicopteros."};
				};
				if ("topdown" in _prof) then {_use pushBack "Ataque por arriba (TopDown): eligelo con el modo de fuego para pegar en el techo del blindado (mas dano); necesita algo de distancia."};
				if ("overfly" in _prof) then {_use pushBack "Modo Overfly: pasa por encima del blanco y explota sobre el (golpea el techo)."};
				if (_rng > 0) then {_use pushBack format ["Distancia maxima de fijacion: unos %1 m.", round _rng]};
			};
		};
	};
	if (_type == 1 && {count _muzzles > 1}) then {
		{
			if ((_x select 0) != "this") then {_use pushBack format ["Lanzagranadas acoplado (%1): cambia a esa boca con la tecla de modo de fuego; las granadas caen en parabola (unos 50-400 m).", _x select 1]};
		} forEach _muzzles;
	};
	//--- descripcion
	private _desc = [getText (_cfg >> "descriptionShort")] call VIOC_GI_fnc_txt;
	if (_desc == "") then {
		_desc = [getText (_cfg >> "Library" >> "libTextDesc")] call VIOC_GI_fnc_txt;
		if (count _desc > 300) then {_desc = (_desc select [0, 300]) + "..."};
	};
	_c = [_name, _kind, _loaded, _muzzles, [_w] call VIOC_GI_fnc_attach, _modes, _zero, _use, _allMags, _desc];
	VIOC_GI_CACHE set [_key, _c];
	_c
};

//--- Todos los cargadores compatibles de un arma (todas las bocas, minusculas). Lo usa la lista vinculada del menu.
VIOC_GI_fnc_weaponMags = {
	params [["_w", "", [""]]];
	if (_w == "" || {!isClass (configFile >> "CfgWeapons" >> _w)}) exitWith {[]};
	+(([_w] call VIOC_GI_fnc_wdata) select 8)
};

//--- Armas de tu tienda (principal, lanzador, pistola).
VIOC_GI_fnc_shopWeapons = {
	private _res = [];
	{
		private _l = missionNamespace getVariable [_x, []];
		if (_l isEqualType []) then {{if (_x isEqualType "") then {_res pushBackUnique (toLower _x)}} forEach _l};
	} forEach ["cti_gear_list_primary", "cti_gear_list_secondary", "cti_gear_list_pistol"];
	_res
};

//--- Indice inverso (cargador -> armas de tu tienda, accesorio -> armas de tu tienda). Se arma una vez, en segundo plano.
VIOC_GI_fnc_buildRev = {
	if (VIOC_GI_REV_BUSY || {count VIOC_GI_REV > 0}) exitWith {};
	VIOC_GI_REV_BUSY = true;
	[] spawn {
		private _mags = createHashMap;
		private _accs = createHashMap;
		{
			private _w = _x;
			if (isClass (configFile >> "CfgWeapons" >> _w)) then {
				private _n = [_w] call VIOC_GI_fnc_name;
				{
					private _l = toLower _x;
					private _a = _mags getOrDefault [_l, []];
					_a pushBackUnique _n;
					_mags set [_l, _a];
				} forEach (compatibleMagazines _w);
				{
					{
						private _a = _accs getOrDefault [_x, []];
						_a pushBackUnique _n;
						_accs set [_x, _a];
					} forEach _x;
				} forEach ([_w] call VIOC_GI_fnc_attach);
			};
		} forEach (call VIOC_GI_fnc_shopWeapons);
		VIOC_GI_REV = [_mags, _accs];
		VIOC_GI_REV_BUSY = false;
		//--- si el panel sigue mostrando un cargador o accesorio, se rehace con la lista de armas
		private _d = uiNamespace getVariable ["cti_dialog_ui_gear", displayNull];
		if (!isNull _d && {!isNull (_d displayCtrl 70060)} && {ctrlShown (_d displayCtrl 70060)} && {VIOC_GI_ITEM != ""} && {!isClass (configFile >> "CfgWeapons" >> VIOC_GI_ITEM) || {getNumber (configFile >> "CfgWeapons" >> VIOC_GI_ITEM >> "type") == 131072}}) then {
			[VIOC_GI_ITEM] call VIOC_GI_fnc_show;
		};
	};
};

//--- "Armas de tu tienda que lo usan: ..." (o "calculando..." la primera vez).
VIOC_GI_fnc_revLine = {
	params ["_c", "_which", "_label"];
	if (count VIOC_GI_REV == 0) exitWith {call VIOC_GI_fnc_buildRev; format ["<t color='#9fd3ff'>%1:</t> <t color='#aaaaaa'>calculando...</t><br/>", _label]};
	private _l = (VIOC_GI_REV select _which) getOrDefault [toLower _c, []];
	if (count _l == 0) exitWith {format ["<t color='#9fd3ff'>%1:</t> <t color='#aaaaaa'>ninguna</t><br/>", _label]};
	private _s = +_l;
	_s sort true;
	private _more = (count _s) - 25;
	if (_more > 0) then {_s resize 25};
	format ["<t color='#9fd3ff'>%1 (%2):</t> %3%4<br/>", _label, count _l, _s joinString ", ", if (_more > 0) then {format [" y %1 mas", _more]} else {""}]
};

//--- Ficha (texto estructurado) de cualquier objeto de la tienda.
VIOC_GI_fnc_render = {
	params [["_item", "", [""]]];
	if (_item == "") exitWith {"<t color='#aaaaaa'>Elige un arma, cargador o accesorio en la lista de la tienda, o usa los botones de arriba para ver las armas de la unidad.</t>"};
	private _level = call VIOC_GI_fnc_level;
	private _shop = [_item] call VIOC_GI_fnc_shop;
	private _ptag = [_shop, _level] call VIOC_GI_fnc_priceTag;
	private _sold = if (_ptag == "") then {"<t color='#aaaaaa'>tu tienda no lo vende</t>"} else {format ["en tu tienda: %1", _ptag]};
	private _wc = configFile >> "CfgWeapons" >> _item;
	private _s = "";
	//--- arma (principal, pistola, lanzador)
	if (isClass _wc && {getNumber (_wc >> "type") in [1, 2, 4]}) exitWith {
		([_item] call VIOC_GI_fnc_wdata) params ["_name", "_kind", "_loaded", "_muzzles", "_acc", "_modes", "_zero", "_use", "", "_desc"];
		private _kindTxt = switch (_kind) do {
			case "AssaultRifle": {"Fusil de asalto"}; case "Rifle": {"Fusil"}; case "MachineGun": {"Ametralladora"};
			case "SniperRifle": {"Fusil de tirador / francotirador"}; case "SubmachineGun": {"Subfusil"}; case "Shotgun": {"Escopeta"};
			case "Handgun": {"Pistola"}; case "GrenadeLauncher": {"Lanzagranadas"}; case "RocketLauncher": {"Lanzacohetes"};
			case "MissileLauncher": {"Lanzamisiles"}; case "Launcher": {"Lanzador"}; default {"Arma"};
		};
		_s = format ["<t size='1.15' color='#ffd27f'>%1</t>  <t size='0.8' color='#888888'>%2</t><br/>", _name, configName _wc];
		_s = _s + format ["<t color='#9fd3ff'>Tipo:</t> %1 (%2)<br/>", _kindTxt, _sold];
		if (_desc != "") then {_s = _s + format ["<t color='#cccccc'>%1</t><br/>", _desc]};
		//--- municion
		private _nAll = 0;
		private _nSold = 0;
		private _mtxt = "";
		{
			_x params ["", "_label", "_mags"];
			if (_label != "") then {_mtxt = _mtxt + format ["<t color='#ffd27f'>Boca: %1</t><br/>", _label]};
			private _rowsSold = [];
			private _others = [];
			{
				private _mc = configFile >> "CfgMagazines" >> _x;
				private _sh = [_x] call VIOC_GI_fnc_shop;
				private _mn = [_x, "CfgMagazines"] call VIOC_GI_fnc_name;
				if (count _sh > 0) then {
					private _tag = [_x] call VIOC_GI_fnc_ammoTag;
					_rowsSold pushBack [_sh select 0, format ["  <t color='#76F563'>+</t> %1 <t color='#aaaaaa'>(%2)</t>%3 - %4<br/>", _mn, getNumber (_mc >> "count"), if (_tag != "") then {format [" <t color='#ffb27f'>%1</t>", _tag]} else {""}, [_sh, _level] call VIOC_GI_fnc_priceTag]];
				} else {
					_others pushBackUnique format ["%1 (%2)", _mn, getNumber (_mc >> "count")];
				};
			} forEach _mags;
			_nAll = _nAll + count _mags;
			_nSold = _nSold + count _rowsSold;
			_rowsSold sort true;
			{_mtxt = _mtxt + (_x select 1)} forEach _rowsSold;
			if (count _rowsSold == 0) then {_mtxt = _mtxt + "  <t color='#F56363'>tu tienda no vende municion para esta boca</t><br/>"};
			if (count _others > 0) then {
				private _more = (count _others) - 30;
				if (_more > 0) then {_others resize 30};
				_mtxt = _mtxt + format ["  <t color='#888888'>Tambien compatibles (no se venden aqui): %1%2</t><br/>", _others joinString ", ", if (_more > 0) then {format [" y %1 mas", _more]} else {""}];
			};
			//--- calibre: descripcion del primer cargador de la boca
			private _cal = [getText (configFile >> "CfgMagazines" >> (_mags select 0) >> "descriptionShort")] call VIOC_GI_fnc_txt;
			if (_cal != "" && {count _cal < 220}) then {_mtxt = _mtxt + format ["  <t color='#aaaaaa'>%1</t><br/>", _cal]};
		} forEach _muzzles;
		_s = _s + format ["<br/><t color='#9fd3ff' size='1.05'>MUNICION</t> <t color='#aaaaaa'>(%1 compatibles, %2 en tu tienda)</t><br/>", _nAll, _nSold];
		if (_loaded != "") then {_s = _s + "  <t color='#ffb27f'>Desechable: viene cargado, no lleva cargadores aparte.</t><br/>"};
		if (count _muzzles == 0) then {_s = _s + "  <t color='#aaaaaa'>sin datos de municion en la configuracion</t><br/>"};
		_s = _s + _mtxt;
		//--- accesorios
		private _atxt = "";
		{
			private _items = _acc select _forEachIndex;
			if (count _items > 0) then {
				private _sold2 = [];
				private _nn = 0;
				{
					private _sh = [_x] call VIOC_GI_fnc_shop;
					if (count _sh > 0) then {_sold2 pushBack format ["%1 %2", [_x] call VIOC_GI_fnc_name, [_sh, _level] call VIOC_GI_fnc_priceTag]} else {_nn = _nn + 1};
				} forEach _items;
				_sold2 sort true;
				_atxt = _atxt + format ["<t color='#ffd27f'>%1</t> <t color='#aaaaaa'>(%2 compatibles, %3 en tu tienda)</t>: %4%5<br/>", _x select 2, count _items, count _sold2,
					if (count _sold2 > 0) then {_sold2 joinString ", "} else {"<t color='#aaaaaa'>ninguno en tu tienda</t>"},
					if (_nn > 0) then {format [" <t color='#888888'>(+%1 que no se venden aqui)</t>", _nn]} else {""}];
			};
		} forEach VIOC_GI_SLOTS;
		if (_atxt == "") then {_atxt = "<t color='#aaaaaa'>no admite accesorios</t><br/>"};
		_s = _s + "<br/><t color='#9fd3ff' size='1.05'>ACCESORIOS</t> <t color='#aaaaaa'>(se ponen arrastrandolos a las ranuras del arma, o con TALLER: Accesorios de armas)</t><br/>" + _atxt;
		//--- uso
		_s = _s + "<br/><t color='#9fd3ff' size='1.05'>COMO SE USA</t><br/>";
		if (count _modes > 0) then {_s = _s + format ["<t color='#ffd27f'>Modos de fuego:</t> %1<br/>", _modes joinString ", "]};
		if (count _zero > 0) then {_s = _s + format ["<t color='#ffd27f'>Alza:</t> %1 a %2 m (Re Pag / Av Pag)<br/>", _zero select 0, _zero select 1]};
		{_s = _s + format ["- %1<br/>", _x]} forEach _use;
		_s
	};
	//--- cargador
	private _mc = configFile >> "CfgMagazines" >> _item;
	if (isClass _mc) exitWith {
		_s = format ["<t size='1.15' color='#ffd27f'>%1</t>  <t size='0.8' color='#888888'>%2</t><br/>", [_item, "CfgMagazines"] call VIOC_GI_fnc_name, configName _mc];
		_s = _s + format ["<t color='#9fd3ff'>Cargador:</t> %1 balas/proyectiles (%2)<br/>", getNumber (_mc >> "count"), _sold];
		private _tag = [_item] call VIOC_GI_fnc_ammoTag;
		if (_tag != "") then {_s = _s + format ["<t color='#9fd3ff'>Uso:</t> <t color='#ffb27f'>%1</t><br/>", _tag]};
		private _d = [getText (_mc >> "descriptionShort")] call VIOC_GI_fnc_txt;
		if (_d != "") then {_s = _s + format ["<t color='#cccccc'>%1</t><br/>", _d]};
		_s + "<br/>" + ([_item, 0, "Armas de tu tienda que lo usan"] call VIOC_GI_fnc_revLine)
	};
	if !(isClass _wc) exitWith {
		private _root = "";
		{if (isClass (configFile >> _x >> _item)) exitWith {_root = _x}} forEach ["CfgVehicles", "CfgGlasses"];
		if (_root == "") exitWith {format ["<t color='#F56363'>Sin datos de configuracion para %1</t> (quizas falta un mod).", [_item] call VIOC_GI_fnc_txt]};
		format ["<t size='1.15' color='#ffd27f'>%1</t>  <t size='0.8' color='#888888'>%2</t><br/>%3<br/><t color='#cccccc'>%4</t>", [_item, _root] call VIOC_GI_fnc_name, configName (configFile >> _root >> _item), _sold, [getText (configFile >> _root >> _item >> "descriptionShort")] call VIOC_GI_fnc_txt]
	};
	//--- accesorio u otro objeto de CfgWeapons
	_s = format ["<t size='1.15' color='#ffd27f'>%1</t>  <t size='0.8' color='#888888'>%2</t><br/>", [_item] call VIOC_GI_fnc_name, configName _wc];
	private _it = getNumber (_wc >> "ItemInfo" >> "type");
	private _si = (VIOC_GI_SLOTS apply {_x select 1}) find _it;
	private _kindTxt = if (_si >= 0) then {format ["accesorio - %1", (VIOC_GI_SLOTS select _si) select 2]} else {([_item] call BIS_fnc_itemType) param [1, "objeto"]};
	_s = _s + format ["<t color='#9fd3ff'>Tipo:</t> %1 (%2)<br/>", _kindTxt, _sold];
	private _d = [getText (_wc >> "descriptionShort")] call VIOC_GI_fnc_txt;
	if (_d != "") then {_s = _s + format ["<t color='#cccccc'>%1</t><br/>", _d]};
	if (_si >= 0) then {_s = _s + "<br/>" + ([_item, 1, "Armas de tu tienda compatibles"] call VIOC_GI_fnc_revLine)};
	_s
};

//--- Crea el panel en el menu de equipo (una vez por apertura del menu). Devuelve true si pudo.
VIOC_GI_fnc_create = {
	params ["_d"];
	private _x0 = safeZoneX + safeZoneW * 0.41;
	private _y0 = safeZoneY + safeZoneH * 0.07;
	private _w = safeZoneW * 0.58;
	private _h = safeZoneH * 0.465;
	private _hh = safeZoneH * 0.04;
	private _bg = _d ctrlCreate ["RscText", 70060];
	if (isNull _bg) exitWith {false};
	_bg ctrlSetPosition [_x0, _y0, _w, _h];
	_bg ctrlSetBackgroundColor [0.04, 0.05, 0.06, 0.96];
	_bg ctrlCommit 0;
	private _t = _d ctrlCreate ["RscStructuredText", 70061];
	_t ctrlSetPosition [_x0 + safeZoneW * 0.005, _y0 + safeZoneH * 0.005, _w * 0.33, _hh];
	_t ctrlSetStructuredText parseText "<t color='#42b6ff'>INFO DEL ARMA</t>";
	_t ctrlCommit 0;
	private _bw = safeZoneW * 0.105;
	private _bx = _x0 + _w - (3 * _bw) - (safeZoneW * 0.045);
	{
		_x params ["_idc", "_txt", "_tip", "_code"];
		private _b = _d ctrlCreate ["RscButton", _idc];
		_b ctrlSetPosition [_bx + _forEachIndex * (_bw + safeZoneW * 0.003), _y0 + safeZoneH * 0.005, _bw, _hh - safeZoneH * 0.008];
		_b ctrlSetText _txt;
		_b ctrlSetTooltip _tip;
		_b ctrlAddEventHandler ["ButtonClick", _code];
		_b ctrlCommit 0;
	} forEach [
		[70062, "Arma principal", "Ficha del arma principal de la unidad que editas", "with missionNamespace do {[0] call VIOC_GI_fnc_showUnit}"],
		[70063, "Lanzador", "Ficha del lanzador de la unidad que editas", "with missionNamespace do {[1] call VIOC_GI_fnc_showUnit}"],
		[70064, "Pistola", "Ficha de la pistola de la unidad que editas", "with missionNamespace do {[2] call VIOC_GI_fnc_showUnit}"]
	];
	private _cl = _d ctrlCreate ["RscButton", 70065];
	_cl ctrlSetPosition [_x0 + _w - safeZoneW * 0.032, _y0 + safeZoneH * 0.005, safeZoneW * 0.028, _hh - safeZoneH * 0.008];
	_cl ctrlSetText "X";
	_cl ctrlSetTooltip "Cerrar la ficha";
	_cl ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_GI_fnc_toggle}"];
	_cl ctrlCommit 0;
	private _g = _d ctrlCreate ["RscControlsGroup", 70066];
	_g ctrlSetPosition [_x0, _y0 + _hh + safeZoneH * 0.006, _w, _h - _hh - safeZoneH * 0.01];
	_g ctrlCommit 0;
	private _tx = _d ctrlCreate ["RscStructuredText", 70067, _g];
	_tx ctrlSetPosition [safeZoneW * 0.005, 0, _w - safeZoneW * 0.025, _h - _hh - safeZoneH * 0.01];
	_tx ctrlCommit 0;
	!isNull _tx
};

//--- Muestra la ficha en el panel (si no esta, en un aviso).
VIOC_GI_fnc_show = {
	params [["_item", "", [""]]];
	private _s = [_item] call VIOC_GI_fnc_render;
	private _d = uiNamespace getVariable ["cti_dialog_ui_gear", displayNull];
	private _tx = if (isNull _d) then {controlNull} else {_d displayCtrl 70067};
	if (isNull _tx || {!ctrlShown (_d displayCtrl 70060)}) exitWith {hintSilent parseText _s};
	_tx ctrlSetStructuredText parseText format ["<t size='0.85'>%1</t>", _s];
	private _g = _d displayCtrl 70066;
	private _p = ctrlPosition _tx;
	_tx ctrlSetPosition [_p select 0, 0, _p select 2, (ctrlTextHeight _tx) max ((ctrlPosition _g) select 3)];
	_tx ctrlCommit 0;
};

//--- Ficha de un arma de la unidad que editas (0 principal, 1 lanzador, 2 pistola).
VIOC_GI_fnc_showUnit = {
	params ["_slot"];
	private _gear = uiNamespace getVariable ["cti_dialog_ui_gear_target_gear", []];
	private _w = "";
	if (_gear isEqualType [] && {count _gear > 0} && {(_gear select 0) isEqualType []}) then {
		private _e = (_gear select 0) param [_slot, []];
		if (_e isEqualType [] && {count _e > 0} && {(_e select 0) isEqualType ""}) then {_w = _e select 0};
	};
	if (_w == "") exitWith {
		private _d = uiNamespace getVariable ["cti_dialog_ui_gear", displayNull];
		private _tx = if (isNull _d) then {controlNull} else {_d displayCtrl 70067};
		private _m = format ["<t color='#aaaaaa'>La unidad no lleva %1.</t>", ["arma principal", "lanzador", "pistola"] select ((_slot max 0) min 2)];
		if (isNull _tx) then {hintSilent parseText _m} else {_tx ctrlSetStructuredText parseText _m};
	};
	VIOC_GI_ITEM = toLower _w;
	[_w] call VIOC_GI_fnc_show;
};

//--- Boton "Info del arma" del pie del menu: abre o cierra el panel.
VIOC_GI_fnc_toggle = {
	private _d = uiNamespace getVariable ["cti_dialog_ui_gear", displayNull];
	if (isNull _d) exitWith {};
	private _show = true;
	if (isNull (_d displayCtrl 70060)) then {
		if !([_d] call VIOC_GI_fnc_create) then {_show = false};
	} else {
		_show = !(ctrlShown (_d displayCtrl 70060));
	};
	if (!_show && {isNull (_d displayCtrl 70067)}) exitWith {hintSilent parseText ([VIOC_GI_ITEM] call VIOC_GI_fnc_render)};	//--- sin panel: la ficha en un aviso
	{
		private _c = _d displayCtrl _x;
		if (!isNull _c) then {_c ctrlShow _show};
	} forEach VIOC_GI_IDCS;
	private _btn = _d displayCtrl 70041;
	if (!isNull _btn) then {_btn ctrlSetText (["Info del arma", "Ocultar info"] select _show)};
	if (_show) then {
		if (VIOC_GI_ITEM == "") then {[0] call VIOC_GI_fnc_showUnit} else {[VIOC_GI_ITEM] call VIOC_GI_fnc_show};
	};
};

//--- Gancho de la lista de la tienda (CTI_UI_Gear_UpdateLinkedItems): recuerda el objeto y, con el panel abierto, muestra su ficha.
VIOC_GI_fnc_onSelect = {
	params [["_item", "", [""]]];
	if (_item == "") exitWith {};
	VIOC_GI_ITEM = _item;
	private _d = uiNamespace getVariable ["cti_dialog_ui_gear", displayNull];
	if (isNull _d) exitWith {};
	private _bg = _d displayCtrl 70060;
	if (isNull _bg || {!ctrlShown _bg}) exitWith {};
	[_item] call VIOC_GI_fnc_show;
};

class VIOC_WEAPON_INFO {
	title = "VIOC: Info del arma en el menu de equipo (municion compatible, accesorios, modos de fuego y como se usa; la lista de cargadores incluye los de magazineWell)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};

class VIOC_Gear_Control_WeaponInfo : CTI_Gear_Control_Clear { //--- VIOC weapon_info: ficha del arma (municion, accesorios, modos, uso)
	idc = 70041;
	x = "SafeZoneX + (SafeZoneW * 0.595)";

	text = "Info del arma";
	tooltip = "Ficha del objeto que eliges en la tienda o de las armas de la unidad: municion compatible (y la que vende tu tienda), accesorios por ranura, modos de fuego y como se usa";
	onLoad = "if ((missionNamespace getVariable ['VIOC_WEAPON_INFO', 1]) < 1) then {(_this select 0) ctrlShow false}";
	action = "with missionNamespace do {if (!isNil 'VIOC_GI_fnc_toggle') then {call VIOC_GI_fnc_toggle}}";
};
